<?php declare(strict_types=1); require_once dirname(__DIR__,2).'/lib/tool-page.php'; $tool=['title'=>'HTML Sanitizer','description'=>'Remove script and unsafe HTML elements from pasted markup locally.','url'=>'https://smarttoolz.in/tools/html-sanitizer/']; smarttoolz_tool_page_start($tool); ?><main class="tool"><h1>HTML Sanitizer</h1><p>Clean pasted HTML by removing scripts and event-handler attributes.</p><textarea id="i" placeholder="Paste HTML"></textarea><button id="go">Sanitize HTML</button><textarea id="o" readonly placeholder="Clean HTML"></textarea></main><style>.tool{max-width:760px;margin:60px auto;padding:24px}.tool textarea{width:100%;min-height:180px;box-sizing:border-box;margin:8px 0;padding:14px;border:1px solid #ddd;border-radius:12px}.tool button{padding:12px 18px;border:0;border-radius:10px;background:#5541ff;color:#fff;font-weight:800}</style><script>go.onclick=()=>{const t=document.createElement('template');t.innerHTML=i.value;t.content.querySelectorAll('script,iframe,object,embed,style').forEach(x=>x.remove());t.content.querySelectorAll('*').forEach(x=>[...x.attributes].forEach(a=>{if(a.name.toLowerCase().startsWith('on')||a.name.toLowerCase()==='srcdoc')x.removeAttribute(a.name)}));o.value=t.innerHTML}</script><?php smarttoolz_tool_page_end(); ?>